'use strict';
// Student Portfolio: profile, achievements with verification, evidence, sharing, CV builder, journey. Private by default.
const P2=MH2;
function achievements(){const ov=st('pfOv',{});return P2.achievements.concat(st('pfNew',[])).map(a=>({...a,status:ov[a.id]||a.status}));}
const achById=id=>achievements().find(a=>a.id===id);
const vBadge=s=>`<span class="mh-vs ${s}">${P2.vStatus[s]}</span>`;
const srcAr={'student-club':'النادي الطلابي',activities:'الأنشطة والمبادرات',training:'المهارات والتدريب',clinical:'السنوات السريرية',manual:'أضفته بنفسك'};
const pfTabs=[['home','ملفي'],['items','الإنجازات'],['cv','السيرة الذاتية'],['share','المشاركة والخصوصية']];
const pfGroups={home:[['home','نظرة عامة'],['journey','رحلتي'],['profile','البيانات الشخصية']],items:[['items','كل الإنجازات'],['add','إضافة خبرة'],['evidence','مكتبة الأدلة'],['verifier','لوحة المراجع']],share:[['share','المشاركات'],['reviewer','كما يراه المراجع']]};
mhViews.portfolio=r=>{
 const body={home:pfHome,journey:pfJourney,profile:pfProfile,items:pfItems,add:pfAdd,evidence:pfEvidence,verifier:pfVerifier,cv:pfCV,share:pfShare,reviewer:pfReviewer,item:()=>pfItem(achById(r.id))}[r.page]||pfHome;
 return `<div class="mh-pf"><header class="mh-head"><div><h1>ملفي الشخصي والإنجازات</h1><p>${icon('lock')} خاص بك افتراضيًا؛ لا يرى أحد شيئًا إلا ما تختار مشاركته.</p></div><div class="mh-head-actions"><button class="btn" data-action="mh-go" data-view="portfolio" data-page="add">${icon('plus')} إضافة خبرة</button></div></header>${sectionNav('portfolio',pfTabs,pfGroups,r.page==='item'?'items':r.page)}${body()}</div>`;
};
function pfCompletion(){const p=P2.profile,checks=[p.headline,p.bio,p.interests.length,p.languages.length,p.links.length,achievements().length>=5,achievements().some(a=>a.status==='verified')];return pctOf(checks.filter(Boolean).length,checks.length);}
function achRow(a){return `<li><button class="mh-achrow" data-action="mh-go" data-view="portfolio" data-page="item" data-id="${a.id}"><span><strong>${e(a.title)}</strong><small>${e(a.org)} · ${a.start}${a.end&&a.end!==a.start?' — '+a.end:a.end?'':' — حتى الآن'} · ${P2.pfCats[a.cat]}</small></span>${vBadge(a.status)}</button></li>`;}
function pfHome(){
 const A=achievements(),p=P2.profile,c=pfCompletion(),by=s=>A.filter(a=>a.status===s).length;
 return `<section class="mh-pf-card"><span class="avatar big">${p.name[0]}</span><div><h2>${p.name}</h2><p>${p.headline}</p><small>${p.program} · ${p.year}</small></div><div class="mh-pf-complete"><b>${c}%</b><span>اكتمال الملف</span>${bar(c)}</div></section>
 <dl class="mh-stats"><div><dt>موثّقة</dt><dd>${by('verified')}</dd></div><div><dt>بانتظار التحقق</dt><dd>${by('pending')}</dd></div><div><dt>مُدخلة ذاتيًا</dt><dd>${by('self')}</dd></div><div><dt>مشاركات نشطة</dt><dd>${pfShares().filter(s=>s.active).length}</dd></div></dl>
 <div class="mh-home-grid"><section><div class="mh-sec-title"><h2>أحدث الإضافات</h2><button class="text-button" data-action="mh-go" data-view="portfolio" data-page="items">الكل ${icon('arrowLeft')}</button></div><ol class="mh-achlist">${A.slice(-4).reverse().map(achRow).join('')}</ol></section>
 <section><h2>بانتظار التحقق</h2><ol class="mh-achlist">${A.filter(a=>a.status==='pending').map(achRow).join('')||'<li class="mh-empty">لا شيء.</li>'}</ol><h2 class="mh-gap">نسخ السيرة الذاتية</h2><ul class="mh-plain">${pfCVs().map(v=>`<li>${icon('file')} ${v.name} <small>${arDate(v.date)}</small></li>`).join('')||'<li>لم تحفظ نسخة بعد.</li>'}</ul></section></div>`;
}
function pfProfile(){const p=P2.profile;
 return `<dl class="mh-dl wide"><div><dt>الاسم المعروض</dt><dd>${p.name}</dd></div><div><dt>البرنامج</dt><dd>${p.program} <span class="mh-vs verified">موثّق</span></dd></div><div><dt>السنة</dt><dd>${p.year} <span class="mh-vs verified">موثّق</span></dd></div><div><dt>العنوان المهني</dt><dd>${p.headline} <span class="mh-vs self">أدخلته</span></dd></div><div><dt>نبذة</dt><dd>${p.bio}</dd></div><div><dt>الاهتمامات</dt><dd>${p.interests.join('، ')}</dd></div><div><dt>اللغات</dt><dd>${p.languages.join('، ')}</dd></div><div><dt>روابط مهنية</dt><dd>${p.links.map(([n,u])=>`${n}: <bdi dir="ltr">${u}</bdi>`).join('، ')}</dd></div></dl><p class="mh-fine">البيانات الجامعية تأتي من سجلك وتظهر كموثّقة؛ ما تكتبه بنفسك يظهر كمُدخل ذاتيًا.</p>`;}
function pfItems(){
 const f=st('pfFilter',{q:'',cat:'all',status:'all',src:'all'}),A=achievements().filter(a=>(f.cat==='all'||a.cat===f.cat)&&(f.status==='all'||a.status===f.status)&&(f.src==='all'||a.source===f.src)&&(!f.q||(a.title+a.org+a.skills.join('')).includes(f.q)));
 const opt=(id,cur,pairs,l)=>`<select id="${id}" aria-label="${l}">${pairs.map(([v,t])=>`<option value="${v}" ${cur===v?'selected':''}>${t}</option>`).join('')}</select>`;
 const cats=Object.keys(P2.pfCats).filter(c=>A.some(a=>a.cat===c));
 return `<div class="mh-filterbar"><label class="search-field">${icon('search')}<input id="pf-q" type="search" placeholder="ابحث بالعنوان أو الجهة أو المهارة" value="${e(f.q)}"></label>${opt('pf-cat',f.cat,[['all','كل التصنيفات'],...Object.entries(P2.pfCats)],'التصنيف')}${opt('pf-status',f.status,[['all','كل الحالات'],...Object.entries(P2.vStatus).slice(0,4)],'حالة التحقق')}${opt('pf-src',f.src,[['all','كل المصادر'],...Object.entries(srcAr)],'المصدر')}</div>
 ${cats.map(c=>`<section class="mh-reggroup"><h2>${P2.pfCats[c]}</h2><ol class="mh-achlist">${A.filter(a=>a.cat===c).map(achRow).join('')}</ol></section>`).join('')||'<p class="mh-empty">لا إنجازات تطابق التصفية.</p>'}`;
}
function pfItem(a){
 const ev=P2.evidenceFiles.filter(x=>x[1]===a.id),req=st('pfReq',{})[a.id];
 return `${crumbs('portfolio',[['الإنجازات','items'],[a.title]])}<article class="mh-svpage"><header><h2>${e(a.title)}</h2>${vBadge(a.status)}</header><dl class="mh-dl"><div><dt>الجهة</dt><dd>${e(a.org)}</dd></div><div><dt>الدور</dt><dd>${e(a.role)}</dd></div><div><dt>الفترة</dt><dd>${a.start} — ${a.end||'حتى الآن'}</dd></div><div><dt>المصدر</dt><dd>${srcAr[a.source]||'أضفته بنفسك'}</dd></div></dl>${a.desc?`<p class="mh-big">${e(a.desc)}</p>`:''}<ul class="mh-tags">${a.skills.map(s=>`<li>${e(s)}</li>`).join('')}</ul>
 ${a.status==='verified'?`<p class="mh-alert soft">${icon('checkCircle')} تحققت منه: ${a.verifier} · ${arDate(a.vdate)}. نطاق التحقق: ${a.cat==='training'?'حضور الدورة، وليس إثبات الكفاءة المهنية':'المشاركة والدور المذكور'}.</p>`:a.status==='self'?`<p class="mh-alert soft">${icon('info')} هذا الإنجاز مُدخل ذاتيًا. ${a.cat==='research'?'قبول الملخص لا يعني نشرًا علميًا.':''}</p><button class="btn" data-action="pf-verify" data-id="${a.id}">طلب التحقق</button>`:a.status==='pending'?`<p class="mh-fine">طلب التحقق ${req?'أُرسل '+arDate(req):'قيد المراجعة لدى الجهة'}.</p>`:''}
 <h3>الأدلة</h3><ul class="mh-plain">${ev.map(([n,,vis])=>`<li>${icon('file')} ${n} <small>${vis}</small></li>`).join('')||'<li>لا أدلة مرفقة.</li>'}</ul></article>`;
}
function pfAdd(){
 return `<form class="mh-apply" id="pf-form"><header><h2>إضافة خبرة أو إنجاز</h2><p>تظهر كـ«مُدخلة ذاتيًا» حتى تتحقق منها جهة مخولة.</p></header><div class="form-grid"><div class="field"><label for="pf-cat2">التصنيف</label><select id="pf-cat2" name="cat">${Object.entries(P2.pfCats).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div class="field"><label for="pf-title">العنوان</label><input id="pf-title" name="title" required maxlength="90"></div><div class="field"><label for="pf-org">الجهة</label><input id="pf-org" name="org" required maxlength="80"></div><div class="field"><label for="pf-role">الدور</label><input id="pf-role" name="role" maxlength="60"></div><div class="field"><label for="pf-start">البداية</label><input id="pf-start" name="start" type="month" required></div><div class="field"><label for="pf-end">النهاية</label><input id="pf-end" name="end" type="month"></div><div class="field full"><label for="pf-desc">الوصف والمسؤوليات</label><textarea id="pf-desc" name="desc" rows="3" maxlength="500"></textarea></div><div class="field full"><label for="pf-skills">المهارات (افصل بفاصلة)</label><input id="pf-skills" name="skills" maxlength="120"></div></div><div class="mh-form-actions"><button class="btn">إضافة</button><button type="button" class="text-button" data-action="mh-go" data-view="portfolio" data-page="items">إلغاء</button></div></form>`;
}
function pfEvidence(){return `<table><thead><tr><th>الدليل</th><th>مرتبط بـ</th><th>من يراه</th></tr></thead><tbody>${P2.evidenceFiles.map(([n,id,vis])=>`<tr><td>${icon('file')} ${n}</td><td>${achById(id)?.title||'—'}</td><td>${vis}</td></tr>`).join('')}</tbody></table><p class="mh-fine">لكل دليل صلاحية عرض خاصة، ويُستخدم في طلب التحقق أو المشاركة بموافقتك فقط.</p>`;}
function pfVerifier(){
 const A=achievements().filter(a=>a.status==='pending');
 return `<p class="mh-lede">معاينة دور المراجع في برنامج التطوع الصحي.</p><ul class="mh-review-list">${A.map(a=>`<li><div><strong>عبدالله الحربي · ${e(a.title)}</strong><small>${e(a.org)} · ${a.start}</small><p>${e(a.desc)}</p></div><div class="mh-review-actions"><button class="btn small" data-action="pf-decide" data-id="${a.id}" data-to="verified">اعتماد</button><button class="btn small secondary" data-action="pf-decide" data-id="${a.id}" data-to="pending">طلب توضيح</button><button class="btn small secondary" data-action="pf-decide" data-id="${a.id}" data-to="rejected">رفض</button></div></li>`).join('')||'<li class="mh-empty">لا طلبات تحقق.</li>'}</ul>`;
}
function pfShares(){return P2.shares.concat(st('pfShares',[])).map(s=>({...s,active:st('pfRevoked',[]).includes(s.id)?false:s.active}));}
function pfShare(){
 const A=achievements();
 return `<section><h2>المشاركات النشطة</h2><ul class="mh-svlist">${pfShares().map(s=>`<li class="${s.active?'':'off'}"><div class="mh-share-row"><span><strong>${s.to}</strong><small>${s.items.length} إنجازات · حتى ${arDate(s.until)} · ${s.active?'نشطة':'مُلغاة'}</small></span>${s.active?`<button class="btn small secondary" data-action="pf-revoke" data-id="${s.id}">إلغاء الصلاحية</button>`:''}</div></li>`).join('')}</ul></section>
 <form class="mh-apply" id="pf-share"><h2 class="mh-gap">مشاركة جديدة</h2><div class="field"><label for="sh-to">الجهة المستقبلة</label><input id="sh-to" required placeholder="مثلًا: فريق البحث العلمي"></div><fieldset class="field mh-share"><legend>اختر الإنجازات</legend>${A.map(a=>`<label><input type="checkbox" name="it" value="${a.id}"> ${e(a.title)} ${vBadge(a.status)}</label>`).join('')}</fieldset><div class="field"><label for="sh-until">صالحة حتى</label><input id="sh-until" type="date" required value="2026-11-30" min="${MH.today}"></div><button class="btn">إنشاء رابط مشاركة</button></form>`;
}
function pfReviewer(){
 const s=pfShares().find(x=>x.active)||pfShares()[0];
 return `<p class="mh-lede">هكذا ترى <b>${s.to}</b> ملفك: الإنجازات المختارة فقط، دون إمكانية التعديل.</p><article class="mh-svpage"><header><h2>${P2.profile.name}</h2><span class="mh-fine">${P2.profile.year}</span></header><ol class="mh-achlist">${s.items.map(achById).map(a=>`<li class="mh-achrow"><span><strong>${e(a.title)}</strong><small>${e(a.org)} · ${a.start}</small></span>${vBadge(a.status)}</li>`).join('')}</ol><p class="mh-fine">${achievements().length-s.items.length} إنجازات مخفية عن هذا المراجع.</p></article>`;
}
function pfCVs(){return st('pfCVs',[]);}
function pfCV(){
 const cv=st('pfCv',{preset:'general',tpl:'clean',cats:P2.cvPresets.general[1],hidden:[]}),A=achievements().filter(a=>cv.cats.includes(a.cat)&&!cv.hidden.includes(a.id)&&a.status!=='rejected'),p=P2.profile;
 return `<div class="mh-cvb"><aside><h2>إعداد السيرة</h2><div class="field"><label for="cv-preset">نوع السيرة</label><select id="cv-preset">${Object.entries(P2.cvPresets).map(([k,[n]])=>`<option value="${k}" ${cv.preset===k?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="cv-tpl">القالب</label><select id="cv-tpl">${Object.entries(P2.cvTemplates).map(([k,n])=>`<option value="${k}" ${cv.tpl===k?'selected':''}>${n}</option>`).join('')}</select></div>
 <fieldset class="mh-share"><legend>الأقسام</legend>${Object.entries(P2.pfCats).map(([k,v])=>`<label><input type="checkbox" data-cvcat="${k}" ${cv.cats.includes(k)?'checked':''}> ${v}</label>`).join('')}</fieldset>
 <fieldset class="mh-share"><legend>الإنجازات الظاهرة</legend>${achievements().filter(a=>cv.cats.includes(a.cat)).map(a=>`<label><input type="checkbox" data-cvhide="${a.id}" ${cv.hidden.includes(a.id)?'':'checked'}> ${e(a.title)}</label>`).join('')}</fieldset>
 <div class="mh-form-actions"><button class="btn" data-action="cv-print">${icon('download')} تصدير PDF</button><button class="btn secondary" data-action="cv-save">حفظ نسخة</button></div><ul class="mh-plain">${pfCVs().map(v=>`<li>${icon('file')} ${v.name}</li>`).join('')}</ul></aside>
 <article class="mh-cv tpl-${cv.tpl}" id="cv-preview" aria-label="معاينة السيرة"><header><h2>${p.name}</h2><p>${p.headline}</p><small>${p.program} · ${p.year}</small></header><section><h3>نبذة</h3><p>${p.bio}</p></section>${cv.cats.filter(c=>A.some(a=>a.cat===c)).map(c=>`<section><h3>${P2.pfCats[c]}</h3>${A.filter(a=>a.cat===c).map(a=>`<div class="cv-item"><div><strong>${e(a.title)}</strong>${a.status==='verified'?' <span class="cv-v">✓ موثّق</span>':''}</div><small>${e(a.org)} · ${a.start}${a.end&&a.end!==a.start?' — '+a.end:a.end?'':' — حتى الآن'}</small>${a.desc?`<p>${e(a.desc)}</p>`:''}</div>`).join('')}</section>`).join('')}<section><h3>اللغات</h3><p>${p.languages.join(' · ')}</p></section></article></div>`;
}
function pfJourney(){
 const f=st('jrFilter','all'),A=achievements().filter(a=>f==='all'||a.cat===f).sort((a,b)=>b.start.localeCompare(a.start));const years=[...new Set(A.map(a=>a.start.slice(0,4)))];
 return `<div class="mh-seg" role="group" aria-label="نوع الإنجاز"><button class="${f==='all'?'active':''}" data-action="jr-f" data-f="all">الكل</button>${['leadership','volunteering','training','research','awards','projects'].map(c=>`<button class="${f===c?'active':''}" data-action="jr-f" data-f="${c}">${P2.pfCats[c]}</button>`).join('')}</div>
 <ol class="mh-journey">${years.map(y=>`<li><h2>${y}</h2><ol>${A.filter(a=>a.start.startsWith(y)).map(a=>`<li><time>${new Date(a.start+'-15').toLocaleDateString('ar-SA-u-ca-gregory-nu-latn',{month:'long'})}</time><button data-action="mh-go" data-view="portfolio" data-page="item" data-id="${a.id}"><strong>${e(a.title)}</strong><small>${P2.pfCats[a.cat]}${a.end?'':' · مستمر'}</small></button>${vBadge(a.status)}</li>`).join('')}</ol></li>`).join('')}<li><h2>2024</h2><ol><li><time>سبتمبر</time><span><strong>بداية الدراسة في كلية الطب</strong></span><span class="mh-vs verified">موثّق</span></li></ol></li></ol>`;
}
mhViews['portfolio:after']=()=>{
 const f=MHS.s.pfFilter;if(f){const bind=(id,k)=>{const el=$('#'+id);el?.addEventListener(el.type==='search'?'input':'change',()=>{f[k]=el.value;MHS.save();renderMH();if(el.type==='search'){const n=$('#'+id);n.focus();n.setSelectionRange(n.value.length,n.value.length);}});};bind('pf-q','q');bind('pf-cat','cat');bind('pf-status','status');bind('pf-src','src');}
 $('#pf-form')?.addEventListener('submit',x=>{x.preventDefault();const d=new FormData(x.target);st('pfNew',[]).push({id:'a-u'+Date.now(),cat:d.get('cat'),title:String(d.get('title')).trim(),org:String(d.get('org')).trim(),role:String(d.get('role')||'').trim(),start:d.get('start'),end:d.get('end')||null,desc:String(d.get('desc')||'').trim(),skills:String(d.get('skills')||'').split(/[،,]/).map(s=>s.trim()).filter(Boolean),status:'self',source:'manual'});MHS.save();mhRoute.portfolio={page:'items'};renderMH(true);toast('أُضيفت الخبرة كمُدخلة ذاتيًا.');});
 $('#pf-share')?.addEventListener('submit',x=>{x.preventDefault();const items=$$('[name="it"]:checked').map(c=>c.value);if(!items.length){toast('اختر إنجازًا واحدًا على الأقل.');return;}st('pfShares',[]).push({id:'sh-u'+Date.now(),to:$('#sh-to').value.trim(),items,until:$('#sh-until').value,active:true});MHS.save();renderMH();toast('أُنشئت المشاركة؛ يمكنك إلغاؤها في أي وقت.');});
 const cv=MHS.s.pfCv;if(cv){$('#cv-preset')?.addEventListener('change',x=>{cv.preset=x.target.value;cv.cats=[...P2.cvPresets[cv.preset][1]];MHS.save();renderMH();});$('#cv-tpl')?.addEventListener('change',x=>{cv.tpl=x.target.value;MHS.save();renderMH();});
  $$('[data-cvcat]').forEach(c=>c.addEventListener('change',()=>{cv.cats=c.checked?[...cv.cats,c.dataset.cvcat]:cv.cats.filter(x=>x!==c.dataset.cvcat);MHS.save();renderMH();}));
  $$('[data-cvhide]').forEach(c=>c.addEventListener('change',()=>{cv.hidden=c.checked?cv.hidden.filter(x=>x!==c.dataset.cvhide):[...cv.hidden,c.dataset.cvhide];MHS.save();renderMH();}));}
};
document.addEventListener('click',ev=>{
 const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='pf-verify'){st('pfOv',{})[b.dataset.id]='pending';st('pfReq',{})[b.dataset.id]=MH.today;MHS.save();renderMH();toast('أُرسل طلب التحقق إلى الجهة المخولة.');}
 else if(a==='pf-decide'){st('pfOv',{})[b.dataset.id]=b.dataset.to;MHS.save();renderMH();toast(b.dataset.to==='verified'?'اعتُمد الإنجاز وأُشعر الطالب.':b.dataset.to==='rejected'?'رُفض مع إشعار الطالب بالسبب.':'طُلب توضيح من الطالب.');}
 else if(a==='pf-revoke'){st('pfRevoked',[]).push(b.dataset.id);MHS.save();renderMH();toast('أُلغيت صلاحية الرابط فورًا.');}
 else if(a==='cv-save'){const cv=MHS.s.pfCv;pfCVs().push({name:P2.cvPresets[cv.preset][0]+' — '+P2.cvTemplates[cv.tpl],date:MH.today});MHS.save();renderMH();toast('حُفظت نسخة السيرة.');}
 else if(a==='cv-print'){document.body.classList.add('printing-cv');window.print();setTimeout(()=>document.body.classList.remove('printing-cv'),500);}
 else if(a==='jr-f'){MHS.s.jrFilter=b.dataset.f;MHS.save();renderMH();}
});
